#!/usr/bin/env node
// Icons are authored in src/icons/set.ts. This generates, from it:
//   src/icons/glyphs/<name>.ts  one module per icon — esbuild splits code by FILE, so an icon used by one page never
//                               rides along with the app's entry because another icon from the same file is there
//   src/icons/all.ts            the barrel of every glyph (what "hadi-march/icons" exports)
//   src/icons/catalog.ts        every icon as plain data in one module, for galleries and pickers
// `--check` fails when any generated file is stale (test/icons.test.js runs it).
import { readFileSync, writeFileSync, mkdirSync, readdirSync, rmSync, existsSync } from "node:fs";
import { fileURLToPath } from "node:url";
const root = fileURLToPath(new URL("..", import.meta.url));
const set = readFileSync(`${root}src/icons/set.ts`, "utf8");
const rows = [...set.matchAll(/^export const (\w+) = \/\* @__PURE__ \*\/ i\(("[^"]+"), (\[[^\]]*\])(, true)?\);/gm)].map(([, id, name, d, fill]) => ({ id, name, d, fill: !!fill }));
const files = new Map();
const HEAD = "// GENERATED by tools/gen-icon-catalog.js from src/icons/set.ts — do not edit.\n";
for (const r of rows) files.set(`src/icons/glyphs/${r.id}.ts`, `${HEAD}import { defineIcon } from "../svg.ts";\n\nexport const ${r.id} = /* @__PURE__ */ defineIcon(${r.name}, ${r.d}${r.fill ? ", true" : ""});\n`);
files.set("src/icons/all.ts", `${HEAD}// Every icon, one module each (see glyphs/).\n${rows.map((r) => `export { ${r.id} } from "./glyphs/${r.id}.ts";`).join("\n")}\n`);
files.set("src/icons/catalog.ts", `${HEAD}// Every icon as data, keyed by its export name.
//   import { ICONS } from "hadi-march/icons/catalog"   (an icon gallery; apps import single icons from "hadi-march/icons")
import type { IconDef } from "./svg.ts";

/** Every built-in icon by name (for icon pickers and search; import single icons to keep bundles small). */
export const ICONS: Readonly<Record<string, IconDef>> = {
${rows.map((r) => `  ${r.id}: { name: ${r.name}, d: ${r.d}${r.fill ? ", fill: true" : ""} },`).join("\n")}
};
`);
const check = process.argv.includes("--check");
const stale = [];
const glyphDir = `${root}src/icons/glyphs`;
const extra = existsSync(glyphDir) ? readdirSync(glyphDir).filter((f) => !files.has(`src/icons/glyphs/${f}`)) : [];
for (const [f, text] of files) {
  let cur = null; try { cur = readFileSync(root + f, "utf8"); } catch { /* missing */ }
  if (cur === text) continue;
  if (check) stale.push(f); else { mkdirSync(`${root}${f.replace(/\/[^/]+$/, "")}`, { recursive: true }); writeFileSync(root + f, text); }
}
if (check) {
  if (stale.length || extra.length) { console.error(`✖ icons stale (${[...stale, ...extra].slice(0, 5).join(", ")}…): node tools/gen-icon-catalog.js`); process.exit(1); }
  console.log(`✔ icons up to date (${rows.length})`);
} else {
  for (const f of extra) rmSync(`${glyphDir}/${f}`);
  console.log(`✔ ${rows.length} icons → glyphs/, all.ts, catalog.ts`);
}
